<?php require_once 'config/database.php';require_once 'includes/auth.php';require_once 'includes/ui.php';requireProfile($conn);$uid=(int)$_SESSION['user_id'];$q=trim($_GET['q']??'');$type=$_GET['type']??'ALL';$cat=(int)($_GET['category_id']??0);$loc=(int)($_GET['location_id']??0);$source=(int)($_GET['source_id']??0);$categories=$conn->query('SELECT id,name FROM categories ORDER BY name');$locations=$conn->query('SELECT id,name FROM locations ORDER BY name');
$where="r.status='VERIFIED'";$params=[];$types='';if(in_array($type,['LOST','FOUND'])){$where.=' AND r.type=?';$types.='s';$params[]=$type;}if($q!==''){$where.=' AND (r.item_name LIKE ? OR r.description LIKE ?)';$types.='ss';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}if($cat>0){$where.=' AND r.category_id=?';$types.='i';$params[]=$cat;}if($loc>0){$where.=' AND r.location_id=?';$types.='i';$params[]=$loc;}$sql="SELECT r.id,r.user_id,r.type,r.item_name,r.image,r.incident_date,c.name category_name,l.name location_name FROM reports r LEFT JOIN categories c ON c.id=r.category_id LEFT JOIN locations l ON l.id=r.location_id WHERE $where ORDER BY r.created_at DESC LIMIT 80";$st=$conn->prepare($sql);if($params)$st->bind_param($types,...$params);$st->execute();$sources=$st->get_result();$selected=null;if($source>0){$x=$conn->prepare("SELECT r.id,r.user_id,r.type,r.item_name,r.description,r.category_id,r.location_id,r.incident_date,r.image,c.name category_name,l.name location_name FROM reports r LEFT JOIN categories c ON c.id=r.category_id LEFT JOIN locations l ON l.id=r.location_id WHERE r.id=? AND r.status='VERIFIED'");$x->bind_param('i',$source);$x->execute();$selected=$x->get_result()->fetch_assoc();$x->close();}
$matches=[];if($selected){if($selected['type']==='LOST'){$x=$conn->prepare("SELECT m.score,m.matching_reason,f.id,f.item_name,f.image,f.incident_date,c.name category_name,l.name location_name,u.name reporter_name FROM matches m JOIN reports f ON f.id=m.found_report_id LEFT JOIN categories c ON c.id=f.category_id LEFT JOIN locations l ON l.id=f.location_id JOIN users u ON u.id=f.user_id WHERE m.lost_report_id=? AND f.status='VERIFIED' ORDER BY m.score DESC");$x->bind_param('i',$source);}else{$x=$conn->prepare("SELECT m.score,m.matching_reason,l.id,l.item_name,l.image,l.incident_date,c.name category_name,loc.name location_name,u.name reporter_name FROM matches m JOIN reports l ON l.id=m.lost_report_id LEFT JOIN categories c ON c.id=l.category_id LEFT JOIN locations loc ON loc.id=l.location_id JOIN users u ON u.id=l.user_id WHERE m.found_report_id=? AND l.status='VERIFIED' ORDER BY m.score DESC");$x->bind_param('i',$source);}$x->execute();$matches=$x->get_result();$x->close();}
$titleForTop='Smart Matching';renderHead('Smart Matching');renderUserNav('matching');?><div class="content animate-in"><div class="section-head"><div><h1 class="hero-title">Smart Matching</h1><p class="muted">Pilih barang yang ingin dicocokkan, lalu sistem mencari laporan lawan yang paling mirip.</p></div></div><form class="card searchbar" method="get"><input class="form-control wide" name="q" value="<?= e($q) ?>" placeholder="Barang apa yang ingin dicocokkan? Contoh: dompet hitam"><select class="form-select" name="type"><option value="ALL">Semua</option><option value="LOST" <?= $type==='LOST'?'selected':'' ?>>Barang Hilang</option><option value="FOUND" <?= $type==='FOUND'?'selected':'' ?>>Barang Ditemukan</option></select><select class="form-select" name="category_id"><option value="0">Semua Kategori</option><?php while($c=$categories->fetch_assoc()): ?><option value="<?= $c['id'] ?>" <?= $cat===$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endwhile; ?></select><select class="form-select" name="location_id"><option value="0">Semua Lokasi</option><?php while($l=$locations->fetch_assoc()): ?><option value="<?= $l['id'] ?>" <?= $loc===$l['id']?'selected':'' ?>><?= e($l['name']) ?></option><?php endwhile; ?></select><button class="btn btn-blue" type="submit">Cari Barang</button></form><?php if(isset($_GET['generated'])): ?><div class="notice notice-ok">Pencocokan selesai. <?= (int)$_GET['generated'] ?> pasangan kecocokan dibuat/diperbarui.</div><?php endif; ?><section class="section"><div class="section-head"><h2>1. Pilih barang</h2><span class="muted"><?= $sources->num_rows ?> laporan terverifikasi</span></div><div class="grid grid-3 stagger"><?php if($sources->num_rows): while($r=$sources->fetch_assoc()): ?><div class="card item-card"><div class="thumb"><?php if($r['image']): ?><img src="uploads/<?= e($r['image']) ?>" alt=""><?php else: ?>🔎<?php endif; ?></div><div class="body"><span class="pill <?= $r['type']==='FOUND'?'pill-green':'pill-red' ?>"><?= $r['type']==='FOUND'?'Ditemukan':'Hilang' ?></span><h3><?= e($r['item_name']) ?></h3><div class="meta">📍 <?= e($r['location_name']??'-') ?> · 📅 <?= e($r['incident_date']) ?></div><div class="actions"><a class="btn btn-light" href="detail-barang.php?id=<?= $r['id'] ?>">Detail</a><a class="btn btn-primary" href="generate-matches.php?source_id=<?= $r['id'] ?>">✦ Cocokkan</a></div></div></div><?php endwhile;else: ?><div class="empty" style="grid-column:1/-1">Tidak ada laporan yang cocok.</div><?php endif; ?></div></section><?php if($selected): ?><section class="section"><div class="section-head"><div><h2>2. Hasil Pencocokan: <?= e($selected['item_name']) ?></h2><p class="muted"><?= e($selected['type']==='LOST'?'Mencari barang ditemukan':'Mencari laporan barang hilang') ?>.</p></div></div><div class="grid grid-2 stagger"><?php if($matches->num_rows): while($m=$matches->fetch_assoc()): ?><div class="card"><div style="display:flex;gap:15px;align-items:center"><div class="thumb" style="width:120px;height:100px;flex:0 0 120px;border-radius:12px"><?php if($m['image']): ?><img src="uploads/<?= e($m['image']) ?>" alt="" style="width:100%;height:100%;object-fit:cover"><?php else: ?>📦<?php endif; ?></div><div style="flex:1"><span class="pill pill-green">Kecocokan <?= (int)$m['score'] ?>%</span><h3 style="margin:8px 0"><?= e($m['item_name']) ?></h3><div class="meta"><?= e($m['category_name']??'-') ?> · <?= e($m['location_name']??'-') ?><br>Pelapor: <?= e($m['reporter_name']) ?></div></div></div><p class="meta" style="margin-top:14px">✓ <?= e($m['matching_reason']) ?></p><div class="progress"><span style="width:<?= min(100,(int)$m['score']) ?>%"></span></div><div class="actions"><a class="btn btn-light" href="detail-barang.php?id=<?= $m['id'] ?>">Lihat Detail</a><?php if($selected['type']==='LOST' && (int)$selected['user_id']===$uid): ?><a class="btn btn-green" href="klaim.php?report_id=<?= $m['id'] ?>&lost_report_id=<?= $selected['id'] ?>">Ajukan Klaim</a><?php endif; ?></div></div><?php endwhile;else: ?><div class="empty" style="grid-column:1/-1">Belum ada kecocokan. Klik “Cocokkan” pada barang untuk menjalankan algoritma.</div><?php endif; ?></div></section><?php endif; ?></div><?php renderFooter(); ?>
